                        const Vector3 t1 = Vector3Normalize(Vector3CrossProduct(up, { 0, 1, 0 })), t2 = Vector3CrossProduct(t1, up);
                        // A spot of each stone kind within 20 km, then dig it until its gem turns up.
                        std::map<std::string, Vector3> spot;
